import math

def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def calculate_d(n):
    # d(n) = tau(n) - 2, provided n > 1.
    if n <= 1:
        return 0 # d(1)=0, as it has no divisors other than 1 and itself.
    tau_n = count_divisors(n)
    return tau_n - 2

# Search strategy: Find the smallest n >= 2 such that d(n) = d(n+735)
# We are looking for the minimum 'a' = d(n).
MAX_N = 10000 # Start with a limited search range
found_a = float('inf')
solution_n = None

for n in range(2, MAX_N):
    d_n = calculate_d(n)
    d_n_plus_735 = calculate_d(n + 735)

    if d_n == d_n_plus_735:
        a = d_n
        if a < found_a:
            found_a = a
            solution_n = n
            # Since we iterate n in increasing order, the first match gives the smallest a
            # UNLESS a smaller a was missed in the previous manual checks (a=0, a=1).
            # Given the manual checks were rigorous, we can stop upon finding the first match.
            break

print(f"Smallest a found: {found_a}")
if solution_n is not None:
    print(f"Corresp. n: {solution_n}")
else:
    print("No solution found within MAX_N")
